                FLAC__ASSERT(options->args.checks.num_shorthand_ops == 0);
                FLAC__ASSERT(options->args.checks.num_major_ops == 1);
                FLAC__ASSERT(options->args.checks.num_major_ops == options->ops.num_operations);
